<?php
require __DIR__.'/support/wp-sqlite.php';
require __DIR__.'/../includes/class-wff-storage.php';
require __DIR__.'/../includes/class-wff-loans.php';
function check($ok,$msg){if(!$ok)throw new Exception($msg);}
function req($fields=array()){return new Request(array_merge(array('hid'=>1),$fields));}
$wpdb=new Database();
$wpdb->query('CREATE TABLE wp_wff_members(household_id INTEGER,user_id INTEGER,role TEXT)');$wpdb->query("INSERT INTO wp_wff_members VALUES(1,1,'owner'),(2,2,'owner')");
$wpdb->query("CREATE TABLE wp_wff_loans(id INTEGER PRIMARY KEY AUTOINCREMENT,household_id INTEGER,scope TEXT,name TEXT,lender TEXT,ledger_next INTEGER DEFAULT 0,tracking_mode TEXT,opening_principal NUMERIC,annual_rate NUMERIC,installments INTEGER,monthly_payment NUMERIC,repayment_total NUMERIC DEFAULT 0,first_due_on TEXT,due_day INTEGER,status TEXT,notes TEXT,created_at TEXT,updated_at TEXT)");
$wpdb->query('CREATE TABLE wp_wff_loan_payments(id INTEGER PRIMARY KEY AUTOINCREMENT,household_id INTEGER,loan_id INTEGER,installment_no INTEGER,due_on TEXT,paid_on TEXT,paid_amount NUMERIC,extra_principal NUMERIC,principal_amount NUMERIC,interest_amount NUMERIC,note TEXT,created_by INTEGER,created_at TEXT,updated_at TEXT,UNIQUE(loan_id,installment_no))');
$wpdb->query('CREATE TABLE wp_wff_loan_amount_changes(id INTEGER PRIMARY KEY AUTOINCREMENT,household_id INTEGER,loan_id INTEGER,installment_no INTEGER,monthly_payment NUMERIC,created_at TEXT,UNIQUE(loan_id,installment_no))');
$wpdb->query("CREATE TABLE wp_wff_transactions(id INTEGER PRIMARY KEY AUTOINCREMENT,household_id INTEGER,occurred_on TEXT,scope TEXT,kind TEXT,category_id INTEGER,amount NUMERIC,note TEXT,payment_status TEXT,loan_id INTEGER,loan_installment INTEGER,payment_method TEXT,created_by INTEGER,created_at TEXT,updated_at TEXT,UNIQUE(loan_id,loan_installment))");
$wpdb->query('CREATE TABLE wp_wff_categories(id INTEGER PRIMARY KEY AUTOINCREMENT,household_id INTEGER,scope TEXT,kind TEXT,name TEXT,color TEXT,created_at TEXT,UNIQUE(household_id,scope,kind,name))');
$wpdb->query('CREATE TABLE wp_wff_activity(id INTEGER PRIMARY KEY AUTOINCREMENT,household_id INTEGER,user_id INTEGER,action TEXT,object_id INTEGER,description TEXT,created_at TEXT)');
$config=array('name'=>'Historical loan','lender'=>'Bank','scope'=>'family','first_due_on'=>'2024-06-10','monthly_payment'=>'17600','installments'=>'60','opening_principal'=>'800000','notes'=>'','status'=>'active');
$saved=WFF_Loans::save_loan(req($config));check(!is_wp_error($saved),'Finite loan saves without APR');$id=$saved['id'];
$normal=WFF_Loans::list_loans(req());check(count($normal['items'][0]['schedule'])<=18,'Initial response remains bounded');check($normal['items'][0]['schedule_complete']===false,'Normal response explicitly signals partial schedule');
$full=WFF_Loans::list_loans(req(array('full_id'=>$id)))['items'][0];check(count($full['schedule'])===60,'Expand returns all sixty months');check($full['schedule'][0]['due_on']==='2024-06-10'&&$full['schedule'][0]['number']===1,'Earliest historical month present');check($full['schedule'][59]['due_on']==='2029-05-10','Term ends exactly at sixty');
check((int)$wpdb->get_var("SELECT count(*) FROM wp_wff_transactions WHERE loan_id=$id")===30,'Elapsed thirty periods generated once in bounded batches');
$paid=req(array('id'=>$id,'installment_no'=>'1','paid_on'=>'2024-06-10','paid_amount'=>'0','principal_amount'=>'15000','interest_amount'=>'2600','note'=>'Historical paid'));
check(!is_wp_error(WFF_Loans::save_payment($paid)),'Past installment can be marked paid');
$txcount=(int)$wpdb->get_var('SELECT COUNT(*) FROM wp_wff_transactions WHERE loan_id='.$id);
check($wpdb->get_var('SELECT occurred_on FROM wp_wff_transactions WHERE loan_id='.$id.' AND loan_installment=1')==='2024-06-10','Historical scheduled date stays in historical ledger month');
$paid['paid_on']='2024-06-12';check(!is_wp_error(WFF_Loans::save_payment($paid)),'Actual date may be explicitly changed');
check($wpdb->get_var('SELECT occurred_on FROM wp_wff_transactions WHERE loan_id='.$id.' AND loan_installment=1')==='2024-06-12','Explicit actual date updates corresponding entry');
check((int)$wpdb->get_var('SELECT COUNT(*) FROM wp_wff_transactions WHERE loan_id='.$id)===$txcount,'Changing payment date never duplicates ledger entry');
$paid['paid_on']='2024-06-10';check(!is_wp_error(WFF_Loans::save_payment($paid)),'Historical date can be corrected');
$paid['installment_no']='30';$paid['paid_on']='2026-11-10';$paid['principal_amount']='14500';$paid['interest_amount']='2500';check(!is_wp_error(WFF_Loans::save_payment($paid)),'Current installment can be marked paid');
$full=WFF_Loans::list_loans(req(array('full_id'=>$id)))['items'][0];check($full['schedule'][0]['status']==='paid'&&$full['schedule'][29]['status']==='paid','Full reload preserves paid flags');
check($full['paid_count']===2&&$full['remaining_installments']===58,'Paid and remaining installment counts');check($full['recorded_total']===34600.0&&$full['planned_total']===1056000.0&&$full['remaining_amount']===1021400.0,'Actual and expected cash totals correct');check($full['remaining_principal']===770500.0,'Interest never reduces principal');
$config['id']=$id;$config['repayment_total']='1100000';check(!is_wp_error(WFF_Loans::save_loan(req($config))),'Contract total can be supplied');$full=WFF_Loans::list_loans(req(array('full_id'=>$id)))['items'][0];check($full['remaining_amount']===1065400.0,'Explicit total overrides automatic amount');
$config['repayment_total']='';$config['monthly_payment']='20000';$config['amount_change_from']='2026-12';check(!is_wp_error(WFF_Loans::save_loan(req($config))),'Monthly revision accepted');$full=WFF_Loans::list_loans(req(array('full_id'=>$id)))['items'][0];check($full['planned_total']===1128000.0,'Expected total respects historical amount revisions');check($full['schedule'][0]['paid_amount']===17600.0,'Actual historical payment unchanged after revision');
$config['installments']='1';check(is_wp_error(WFF_Loans::save_loan(req($config))),'Cannot shrink below highest recorded paid installment');$config['installments']='60';
check(is_wp_error(WFF_Loans::list_loans(req(array('hid'=>2,'full_id'=>$id)))),'Other household cannot read full history');
// A former unlimited tracker can receive its true maturity without retaining excess unpaid projections.
$other=array_merge($config,array('id'=>null,'name'=>'Unpaid old loan','monthly_payment'=>'100','installments'=>'','repayment_total'=>'','opening_principal'=>''));unset($other['amount_change_from']);
$second=WFF_Loans::save_loan(req($other))['id'];WFF_Loans::list_loans(req());check((int)$wpdb->get_var("SELECT count(*) FROM wp_wff_transactions WHERE loan_id=$second")===30,'Unbounded old loan initially has all elapsed projections');
$other['id']=$second;$other['installments']='24';check(!is_wp_error(WFF_Loans::save_loan(req($other))),'Real term can be set after historical creation');check((int)$wpdb->get_var("SELECT count(*) FROM wp_wff_transactions WHERE loan_id=$second")===24,'Only excess unpaid projections removed');WFF_Loans::generate(1);check((int)$wpdb->get_var("SELECT count(*) FROM wp_wff_transactions WHERE loan_id=$second")===24,'Generation stops at configured term');
// Destructive action requires the named confirmation and owner authorization, and preserves the accounting ledger.
check(is_wp_error(WFF_Loans::delete_loan(req(array('id'=>$id)))),'Unconfirmed deletion rejected');
$del=req(array('id'=>$id,'confirm_delete'=>true,'confirmation_name'=>'Historical loan'));
$wpdb->query("UPDATE wp_wff_members SET role='editor' WHERE household_id=1");check(is_wp_error(WFF_Loans::delete_loan($del)),'Editor cannot delete loan');$wpdb->query("UPDATE wp_wff_members SET role='owner' WHERE household_id=1");
$wpdb->fail_update=true;check(is_wp_error(WFF_Loans::delete_loan($del)),'Ledger detach failure aborts deletion');check((int)$wpdb->get_var("SELECT count(*) FROM wp_wff_loans WHERE id=$id")===1,'Failed deletion rolls back loan');$wpdb->fail_update=false;
$count=(int)$wpdb->get_var('SELECT count(*) FROM wp_wff_transactions');check(!is_wp_error(WFF_Loans::delete_loan($del)),'Confirmed deletion succeeds');check((int)$wpdb->get_var('SELECT count(*) FROM wp_wff_transactions')===$count,'All existing financial ledger entries retained');check((int)$wpdb->get_var("SELECT count(*) FROM wp_wff_transactions WHERE loan_id=$id")===0,'Retained records detached from removed loan');check((int)$wpdb->get_var("SELECT count(*) FROM wp_wff_loan_payments WHERE loan_id=$id")===0,'Loan-specific journal removed');check((int)$wpdb->get_var("SELECT count(*) FROM wp_wff_loan_amount_changes WHERE loan_id=$id")===0,'Loan-specific settings removed');check((int)$wpdb->get_var("SELECT count(*) FROM wp_wff_loans WHERE id=$second")===1,'Other loan untouched');check(is_wp_error(WFF_Loans::save_payment($paid)),'Removed loan cannot be resurrected by a stale payment form');
echo "Loan management: all months from 2024, paid flags, finite generation, totals, principal, revisions and confirmed deletion rollback passed\n";
